#nullable enable // autogenerated

using System.Collections.Generic;
using MVZ2.GameContent.Buffs;
using MVZ2.Vanilla.Artifacts;
using MVZ2.Vanilla.Audios;
using MVZ2.Vanilla.Level;
using MVZ2.Vanilla.Properties;
using MVZ2Logic;
using MVZ2Logic.Artifacts;
using MVZ2Logic.Definitions;
using MVZ2Logic.Entities;
using MVZ2Logic.Level;
using PVZEngine.Auras;
using PVZEngine.Buffs;
using PVZEngine.Callbacks;
using PVZEngine.Level;
using PVZEngine.SeedPacks;

namespace MVZ2.GameContent.Artifacts
{
    [AutoArtifactDefinition(VanillaArtifactNames.cowHorn)]
    public class CowHorn : ArtifactDefinition
    {
        public CowHorn(string nsp, string name) : base(nsp, name)
        {
            AddAura(new Aura());
            AddTrigger(LevelCallbacks.POST_WAVE, PostWaveCallback);
        }
        public override void PostUpdate(Artifact artifact)
        {
            base.PostUpdate(artifact);
            var number = artifact.GetNumber();

            if (number > 0)
            {
                artifact.SetGlowing(true);
                if (artifact.RunAndPassedOneSecond())
                {
                    number--;
                    if (number <= 0)
                    {
                        var aura = artifact.GetAuraEffect<Aura>();
                        aura?.UpdateAura();
                        number = -1;
                    }
                    artifact.SetNumber(number);
                }
            }
            else
            {
                artifact.SetGlowing(false);
            }
        }
        private void PostWaveCallback(LevelCallbacks.PostWaveParams args, CallbackResultVoid result)
        {
            var level = args.level;
            var wave = args.wave;
            if (!level.IsHugeWave(wave) || !level.IsNormalLevelProgression())
                return;
            var artifact = level.GetArtifact(GetID());
            if (artifact != null)
            {
                artifact.SetNumber(GetMaxCooldownSeconds(artifact));
                artifact.Highlight();

                level.PlaySound(VanillaSoundID.raidhorn);

                using var seedPacksItem = level.GetAllSeedPacksDisposeable();
                foreach (var seed in seedPacksItem.Value)
                {
                    if (seed == null)
                        continue;
                    seed.FullRecharge();
                }
                var aura = artifact.GetAuraEffect<Aura>();
                aura?.UpdateAura();
            }
        }
        public static int GetMaxCooldownSeconds(Artifact artifact) => artifact.GetProperty<int>(PROP_MAX_COOLDOWN_SECONDS);
        public static void SetMaxCooldownSeconds(Artifact artifact, int value) => artifact.SetProperty(PROP_MAX_COOLDOWN_SECONDS, value);
        public static readonly VanillaArtifactPropertyMeta<int> PROP_MAX_COOLDOWN_SECONDS = new VanillaArtifactPropertyMeta<int>("max_cooldown_seconds", 15);
        public class Aura : AuraEffectDefinition
        {
            public Aura() : base(VanillaBuffID.SeedPack.cowHorn, 7)
            {
            }

            public override void GetAuraTargets(AuraEffect auraEffect, List<IBuffTarget> results)
            {
                var sourceArtifact = auraEffect.Source as Artifact;
                if (sourceArtifact == null)
                    return;
                if (sourceArtifact.GetNumber() <= 0)
                    return;
                var level = sourceArtifact.Level;

                using var seedPacksItem = level.GetAllSeedPacksDisposeable();
                foreach (var seed in seedPacksItem.Value)
                {
                    if (seed == null)
                        continue;
                    results.Add(seed);
                }
            }
        }
    }
}
